\title{A Tropical Threshold for Vietoris--Rips Completeness:\\
One Scalar Governs Every Dimension}
\author{Aristotle (Harmonic)}
\date{2026-06-16}

\begin{document}
\maketitle

\begin{abstract}
We study the Vietoris--Rips filtration of a finite pseudo-extended-metric space
through the lens of the max-plus (tropical) semiring. To each cloud we attach a
single scalar, the \emph{tropical birth aggregate} $\tropBirthSum$, defined as
the tropical sum---that is, the supremum---of the birth times $\edist(x,y)$ of
all edges. Our central result is a \emph{threshold theorem}: the Rips
$1$-skeleton is complete at scale $\varepsilon$ if and only if
$\tropBirthSum \le \varepsilon$. We then prove that the \emph{same} scalar
governs completeness in every dimension: for any clique size $m$ with
$2 \le m \le n$, all $m$-element cliques are present at scale $\varepsilon$ if
and only if $\tropBirthSum \le \varepsilon$. On the combinatorial side, the
number of $m$-cliques is monotone in $\varepsilon$ and attains its maximum
$\binom{n}{m}$ exactly at this same tropical threshold, yielding a
discrete-to-tropical reconstruction principle. We catalogue the supporting
structure---a finite extension lemma, monotonicity, isometry invariance,
identification with the metric diameter, and product laws---and record
falsifiable conjectures linking the completeness threshold to the connectivity
(single-linkage / spanning-tree minimax) threshold. All results have been
formally verified.
\end{abstract}

\textbf{Keywords.} Vietoris--Rips complex, tropical geometry, max-plus
semiring, persistent homology, topological data analysis, clique counting,
metric diameter, single-linkage clustering.

\section{Introduction}

\subsection{Motivation}
The Vietoris--Rips complex is the workhorse of computational topology. Given a
finite metric space $(\alpha, d)$ and a scale parameter $\varepsilon \ge 0$, one
forms a simplicial complex $\Rips(\alpha, \varepsilon)$ whose simplices are the
finite subsets of diameter at most $\varepsilon$. Letting $\varepsilon$ increase
produces a \emph{filtration}---a nested family of complexes---whose persistent
homology is the central invariant of topological data analysis (TDA).

Tropical geometry replaces ordinary arithmetic $(+, \times)$ by the max-plus
semiring $(\max, +)$. The two subjects meet whenever the \emph{extremal}
behavior of a family of weights, rather than their aggregate sum or product,
controls a phenomenon. This paper makes that meeting precise for the
\emph{completeness} of the Rips complex: the scale at which
$\Rips(\alpha, \varepsilon)$ becomes the full simplex on $\alpha$.

\subsection{Contributions}
We prove, over an arbitrary finite \emph{pseudo-extended-metric space}
(distances in $\Rnn = [0, \infty]$, with $d(x,y) = 0$ permitted for
$x \ne y$):
\begin{enumerate}
  \item The \textbf{tropical birth aggregate} (Definition~\ref{def:trop}) and
  its \textbf{threshold characterization} (Theorem~\ref{thm:threshold}):
  completeness of the $1$-skeleton $\iff \tropBirthSum \le \varepsilon$.
  \item A \textbf{finite extension lemma} (Lemma~\ref{lem:ext}) growing any
  edge to a clique of prescribed size.
  \item The \textbf{same-threshold theorem} in all dimensions
  (Theorems~\ref{thm:allm}--\ref{thm:allmtrop}): for $2 \le m \le n$, all
  $m$-cliques present $\iff \tropBirthSum \le \varepsilon$.
  \item \textbf{Monotonicity} (Proposition~\ref{prop:mono}) and the
  \textbf{saturation theorem} (Theorems~\ref{thm:sat}--\ref{thm:sattrop}): the
  $m$-clique count equals $\binom{n}{m} \iff \tropBirthSum \le \varepsilon$.
  \item Structural results: \textbf{isometry invariance}, \textbf{diameter
  identification}, and \textbf{product laws} (Section~\ref{sec:struct}).
  \item Falsifiable \textbf{conjectures} relating completeness to connectivity
  via spanning-tree minimax (Section~\ref{sec:conj}).
\end{enumerate}
All statements have been formalized and machine-checked.

\section{Preliminaries}

\subsection{Pseudo-extended-metric spaces}
Throughout, $\alpha$ is a finite type with a \emph{pseudo-extended-metric}: a
function $\edist : \alpha \times \alpha \to \Rnn$ that is symmetric, satisfies
the triangle inequality, and has $\edist(x,x) = 0$. We do \emph{not} assume
$\edist(x,y) = 0 \Rightarrow x = y$ (the ``pseudo'' relaxation) nor finiteness
of distances (the ``extended'' relaxation). We write $n = |\alpha|$ and
$\binom{n}{m}$ for the binomial coefficient.

\subsection{The max-plus semiring}
The \emph{tropical} (max-plus) semiring on $\Rnn$ has tropical addition
$a \oplus b = \max(a,b)$ and tropical multiplication $a \otimes b = a + b$.
Tropical addition is commutative, associative, and idempotent; tropical
multiplication distributes over it because $a + \max(b,c) = \max(a+b, a+c)$. The
tropical \emph{sum} of a finite family is its supremum.

\subsection{The Vietoris--Rips complex}
For a scale $\varepsilon \in \Rnn$, a finite subset $s \subseteq \alpha$ is a
\emph{simplex} of $\Rips(\alpha, \varepsilon)$ when $\edist(x,y) \le \varepsilon$
for all $x, y \in s$. The complex is \emph{complete} at scale $\varepsilon$ when
every pair of distinct points is an edge.

\section{The tropical birth aggregate}

\begin{definition}[tropical birth aggregate]\label{def:trop}
The \emph{tropical birth aggregate} of $\alpha$ is the tropical sum of the edge
birth times,
\[
  \tropBirthSum(\alpha) \;:=\; \bigsqcup_{\substack{x, y \,:\, \alpha \\ x \ne y}} \edist(x,y),
\]
the supremum over all pairs of distinct points. When $|\alpha| \le 1$ the index
set is empty and the supremum is the bottom element $0$ of $\Rnn$ (the tropical
zero $-\infty$ in the real $\mathrm{WithBot}\,\mathbb{R}$ model).
\end{definition}

\begin{definition}[Rips clique]\label{def:clique}
For $\varepsilon \in \Rnn$, a finite set $s \subseteq \alpha$ is a
\emph{Rips clique at scale $\varepsilon$}, written $\IsRipsClique(\varepsilon, s)$,
when $\forall\, x, y \in s,\ x \ne y \Rightarrow \edist(x,y) \le \varepsilon$.
\end{definition}

\begin{definition}[clique count]\label{def:count}
The \emph{$m$-clique count} at scale $\varepsilon$ is
\[
  \cliqueCount(m, \varepsilon) \;:=\;
  \bigl|\, \{\, s \subseteq \alpha : |s| = m,\ \IsRipsClique(\varepsilon, s) \,\} \,\bigr|.
\]
\end{definition}

\section{The threshold theorem}

\begin{theorem}[completeness $\iff$ tropical threshold]\label{thm:threshold}
For every $\varepsilon \in \Rnn$,
\[
  \bigl(\forall x, y : \alpha,\ x \ne y \Rightarrow \edist(x,y) \le \varepsilon\bigr)
  \quad\Longleftrightarrow\quad \tropBirthSum(\alpha) \le \varepsilon.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The supremum of a family is $\le \varepsilon$ iff every member is
$\le \varepsilon$. Specializing, $\tropBirthSum(\alpha) \le \varepsilon$ iff
$\edist(x,y) \le \varepsilon$ for all distinct $x, y$. The forward direction of
the stated equivalence drops the trivially satisfied diagonal case $x = y$
(where $\edist(x,x) = 0 \le \varepsilon$); the backward direction reinstates it.
\end{proof}

\begin{corollary}[completeness corollary]\label{cor:complete}
The Rips $1$-skeleton is complete at scale $\varepsilon$ iff
$\tropBirthSum(\alpha) \le \varepsilon$.
\end{corollary}

\section{The finite extension lemma}

\begin{lemma}[finite extension]\label{lem:ext}
Let $x \ne y$ in $\alpha$ and $2 \le m \le n$. Then there is a finite set
$s \subseteq \alpha$ with $|s| = m$, $x \in s$, and $y \in s$.
\end{lemma}

\begin{proof}[Proof sketch]
The pair $\{x,y\}$ has cardinality $2$. Since $2 \le m \le n$, the
superset-of-prescribed-cardinality principle yields a superset
$s \supseteq \{x,y\}$ with $|s| = m$; both $x, y \in \{x,y\} \subseteq s$.
\end{proof}

\section{The same-threshold theorem in all dimensions}

\begin{theorem}[all $m$-cliques $\iff$ complete $1$-skeleton]\label{thm:allm}
For $2 \le m \le n$,
\[
  \bigl(\forall s \subseteq \alpha,\ |s| = m \Rightarrow \IsRipsClique(\varepsilon, s)\bigr)
  \iff
  \bigl(\forall x, y : \alpha,\ x \ne y \Rightarrow \edist(x,y) \le \varepsilon\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) Given distinct $x, y$, use Lemma~\ref{lem:ext} to obtain an
$m$-set $s$ containing both; by hypothesis $s$ is a clique, so
$\edist(x,y) \le \varepsilon$. ($\Leftarrow$) Any $m$-set is a clique because
each of its distinct pairs is within $\varepsilon$.
\end{proof}

\begin{theorem}[same tropical threshold in every dimension]\label{thm:allmtrop}
For $2 \le m \le n$,
\[
  \bigl(\forall s \subseteq \alpha,\ |s| = m \Rightarrow \IsRipsClique(\varepsilon, s)\bigr)
  \iff \tropBirthSum(\alpha) \le \varepsilon.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Chain Theorem~\ref{thm:allm} with Theorem~\ref{thm:threshold}.
\end{proof}

\begin{remark}
The threshold is independent of $m$: a clique of any size requires all its
internal edges, and the binding constraint is the single longest edge anywhere,
whose value is $\tropBirthSum$. At the instant $\varepsilon$ reaches
$\tropBirthSum$, every clique of every admissible size appears at once, and the
entire Vietoris--Rips complex collapses to a single tropical scalar.
\end{remark}

\section{Counting, monotonicity, and saturation}

\begin{proposition}[monotonicity]\label{prop:mono}
If $\varepsilon_1 \le \varepsilon_2$ then every Rips clique at scale
$\varepsilon_1$ is one at scale $\varepsilon_2$; hence
$\cliqueCount(m, \varepsilon_1) \le \cliqueCount(m, \varepsilon_2)$.
\end{proposition}

\begin{proof}[Proof sketch]
If $\edist(x,y) \le \varepsilon_1 \le \varepsilon_2$ then
$\edist(x,y) \le \varepsilon_2$, so the cliqueness predicate is monotone in
$\varepsilon$; cardinality is monotone under the induced inclusion.
\end{proof}

\begin{theorem}[saturation $\iff$ all cliques]\label{thm:sat}
For every $m$,
\[
  \cliqueCount(m, \varepsilon) = \binom{n}{m}
  \iff
  \bigl(\forall s \subseteq \alpha,\ |s| = m \Rightarrow \IsRipsClique(\varepsilon, s)\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
There are $\binom{n}{m}$ subsets of size $m$. The clique count is the
cardinality of the filter of $\IsRipsClique(\varepsilon, \cdot)$ over those
subsets; a filtered finset has full cardinality iff the predicate holds
everywhere.
\end{proof}

\begin{theorem}[counting form of the tropical bridge]\label{thm:sattrop}
For $2 \le m \le n$,
\[
  \cliqueCount(m, \varepsilon) = \binom{n}{m} \iff \tropBirthSum(\alpha) \le \varepsilon.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Chain Theorem~\ref{thm:sat} with Theorem~\ref{thm:allmtrop}.
\end{proof}

\begin{remark}[reconstruction principle]
The integer invariant $\cliqueCount(m, \cdot)$ saturates exactly where the
tropical invariant $\tropBirthSum$ clears $\varepsilon$. Since clique counts are
monotone and integer-valued, the least $\varepsilon$ at which the staircase
reaches $\binom{n}{m}$ recovers $\tropBirthSum$ exactly.
\end{remark}

\section{Structural properties}\label{sec:struct}

\subsection{Monotonicity / functoriality}
The edge count $\operatorname{simplexCount} : \mathbb{R} \to \mathbb{N}$ is
monotone in the scale, exhibiting Rips as a functor on $(\mathbb{R}, \le)$.
Under a $1$-Lipschitz surjection the tropical aggregate is monotone, giving
one-sided functoriality of $X \mapsto \tropBirthSum(X)$.

\subsection{Isometry invariance}
\begin{theorem}[isometry invariance]\label{thm:iso}
An isometric bijection $f : \alpha \to \beta$ (with
$\edist(f x, f y) = \edist(x,y)$ and $f$ bijective) induces
$\tropBirthSum(\alpha) = \tropBirthSum(\beta)$; likewise for the edge count.
\end{theorem}

\subsection{Identification with the diameter}
\begin{theorem}[diameter identification]\label{thm:diam}
For a finite pseudometric space with at least two points,
$\tropBirthSum(\alpha) = \diam(\mathrm{univ})$, the metric diameter. The
supremum over distinct pairs differs from the diameter's supremum only by
diagonal $0$-terms, which do not affect the value once a distinct pair exists.
\end{theorem}

\subsection{Product laws}
\begin{theorem}[$\ell^\infty$ product law]\label{thm:prod}
For finite pseudometric spaces $\alpha, \beta$ with the sup ($\ell^\infty$)
product metric,
\[
  \tropBirthSum(\alpha \times \beta)
  = \max\bigl(\tropBirthSum(\alpha), \tropBirthSum(\beta)\bigr)
  = \tropBirthSum(\alpha) \oplus \tropBirthSum(\beta).
\]
For the $\ell^1$ product metric one has only
$\tropBirthSum(\alpha \times \beta) \le \tropBirthSum(\alpha) + \tropBirthSum(\beta)$.
\end{theorem}

\section{Algorithms}
Let $D$ be the $n \times n$ matrix of pairwise distances.
\begin{itemize}
  \item \textbf{Tropical birth aggregate:}
  $\tropBirthSum(D) = \max_{i < j} D_{ij}$, in $O(n^2)$; by
  Theorem~\ref{thm:diam} this is the diameter.
  \item \textbf{Completeness query:} return $\tropBirthSum(D) \le \varepsilon$
  (Theorem~\ref{thm:threshold}); $O(n^2)$ precompute, $O(1)$ per query, valid in
  every dimension by Theorem~\ref{thm:allmtrop}.
  \item \textbf{Clique count:} enumerate $\binom{n}{m}$ subsets,
  $O\!\bigl(\binom{n}{m} m^2\bigr)$; saturation is detectable in $O(n^2)$ via
  Theorem~\ref{thm:sattrop}.
  \item \textbf{Connectivity threshold:} spanning-tree minimax
  $\min_T \max_{e \in T} D_e$ (largest MST edge), $O(n^2 \log n)$; the
  single-linkage bottleneck, generally $< \tropBirthSum$.
\end{itemize}

\section{Conjectures and future work}\label{sec:conj}

\begin{conjecture}[connectivity = tropical minimax / single-linkage]
For $n \ge 2$, the connectivity threshold
$\varepsilon_c = \inf\{\varepsilon : \Rips(\alpha,\varepsilon)\text{ connected}\}$
equals $\min_T \max_{e \in T} d(e)$, the largest edge of the minimum spanning
tree. Completeness uses $\max$ over all edges; connectivity uses
$\min$-over-trees of the $\max$ edge. For $\{0,1,3,7\} \subset \mathbb{R}$,
$\varepsilon_c = 4$ (the largest minimum-spanning-tree edge $3\mapsto 7$) while
$\tropBirthSum = 7$.
\end{conjecture}

\begin{conjecture}[$\tropBirthSum$ is the diameter]
For $n \ge 2$, $\tropBirthSum(\alpha) = \diam(\mathrm{univ})$
(Theorem~\ref{thm:diam}), the anchor identifying the tropical invariant with the
classical one.
\end{conjecture}

The remaining mission conjectures are established above: the product law
(Theorem~\ref{thm:prod}), the monotone-count characterization
(Theorem~\ref{thm:sattrop}), the functor laws (Theorem~\ref{thm:iso}), and the
higher-simplex same-threshold result (Theorem~\ref{thm:allmtrop}). The principal
open problem is the connectivity contrast above, which would realize
single-linkage clustering inside the tropical semiring.

\section{Conclusion}
The Vietoris--Rips complex of a finite metric space has a completeness threshold
governed by a single tropical scalar. The tropical birth aggregate
$\tropBirthSum$---the max-plus sum of edge birth times---equals the diameter, is
an isometry invariant, combines by tropical addition under $\ell^\infty$
products, and simultaneously controls completeness, clique saturation, and the
full-skeleton threshold in every dimension.

