random.seed(7)
def euclid(a, b):
    return hypot(a[0]-b[0], a[1]-b[1])
def tbs(P):
    n=len(P); return max(euclid(P[i],P[j]) for i in range(n) for j in range(i+1,n))
for t in range(3):
    P=[(random.uniform(-5,5),random.uniform(-5,5)) for _ in range(6)]
    th,tx,ty=0.9,2.0,-1.0
    Q=[(math.cos(th)*x-math.sin(th)*y+tx, math.sin(th)*x+math.cos(th)*y+ty) for x,y in P]
    print(f'trial {t}: tropBirthSum={tbs(P):.6f}  diameter={tbs(P):.6f}  isometry-image={tbs(Q):.6f}')

