function TROP_BIRTH_SUM(D[0..n-1][0..n-1]):
    if n <= 1: return -infinity        # tropical zero (empty sup)
    best <- -infinity
    for i in 0..n-1:
        for j in i+1..n-1:
            best <- max(best, D[i][j])  # tropical addition = max
    return best

